 "content": "def transform(grid):
    """Trace the 2 path through repeated one-cell openings in parallel 8-walls."""
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])

    # Horizontal walls: carry the active columns down through the nearest
    # openings, joining each set of connections on the blank row above.
    wall_rows = [r for r, row in enumerate(a) if 8 in row]
    wall_cols = [c for c in range(w) if any(a[r][c] == 8 for r in range(h))]
    if len(wall_rows) >= 1 and (len(wall_cols) == 0 or len(wall_rows) >= len(wall_cols)):
        seeds = [(r, c) for r in range(h) for c in range(w) if a[r][c] == 2]
        if not seeds:
            return a
        sr, sc = seeds[0]
        active = [sc]
        prev = sr
        for r in wall_rows:
            if r <= prev:
                continue
            holes = [c for c in range(w) if a[r][c] == 0]
            if not holes:
                prev = r
                continue
            chosen = set()
            for x in active:
                d = min(abs(y - x) for y in holes)
                chosen.update(y for y in holes if abs(y - x) == d)
            if r > 0:
                lo = min(active + list(chosen))
                hi = max(active + list(chosen))
                for c in range(lo, hi + 1):
                    if a[r - 1][c] == 0:
                        a[r - 1][c] = 2
            for c in chosen:
                if a[r][c] == 0:
                    a[r][c] = 2
            # The paths continue vertically through the blank rows to the next wall.
            next_wall = next((q for q in wall_rows if q > r), h)
            for rr in range(r + 1, next_wall):
                for c in chosen:
                    if a[rr][c] == 0:
                        a[rr][c] = 2
            active = sorted(chosen)
            prev = r
        # Continue the final open channels to the bottom edge.
        if wall_rows:
            last = max((r for r in wall_rows if r > sr), default=sr)
            for rr in range(last + 1, h):
                for c in active:
                    if a[rr][c] == 0:
                        a[rr][c] = 2
        return a

    # Vertical walls (the rotated maze layout): choose the nearest opening in
    # each wall, mark its adjacent channel, and continue horizontally through it.
    if wall_cols:
        seeds = [(r, c) for r in range(h) for c in range(w) if a[r][c] == 2]
        if not seeds:
            return a
        sr, sc = seeds[0]
        active = [sr]
        first = min((c for c in wall_cols if c > sc), default=w)
        for c in range(sc, first):
            if a[sr][c] == 0:
                a[sr][c] = 2
        for c in [x for x in wall_cols if x > sc]:
            holes = [r for r in range(h) if a[r][c] == 0]
            if not holes:
                continue
            chosen = set()
            for y in active:
                d = min(abs(x - y) for x in holes)
                chosen.update(x for x in holes if abs(x - y) == d)
            left = c - 1
            for y in chosen:
                for rr in range(y + 1):
                    if y > min(active):
                        if a[rr][left] == 0:
                            a[rr][left] = 2
                for rr in range(y, h):
                    if y < max(active):
                        if a[rr][left] == 0:
                            a[rr][left] = 2
                # Extend from this opening through the next channel, or to the edge.
                next_wall = next((x for x in wall_cols if x > c), w)
                for cc in range(left, next_wall):
                    if a[y][cc] == 0:
                        a[y][cc] = 2
            active = sorted(chosen)
        return a
    return a
